  (void)im;
  const unsigned r = (c >> 16) & 0xff, g = (c >> 8) & 0xff, b = c & 0xff;
  canvas_point(binaryring_window, x, y,
               px_swap((uint16_t)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3))));
  return 0;
}
